import { isProxy, Log, objectCountUtils, proxyUtils, storeUtils, toParentWatchProxy, toProxy, watchUpdates } from '@fanfanlo';
import _ from 'lodash';
import { ulid } from 'ulid';
import store from 'store2';
import { createDefaultProject, createDefaultTriggerActionGroup } from '../utils/defaults';
import { IProject } from '../entities/IProject';
import { createDefaultProjectSettings, IProjectSettings } from '../types/IProjectSettings';
import { syncProject } from '../utils/projectMerge';

export const s = storeUtils.namespace('project-v2');
const listName = 'list';
const draftName = 'draft';
const projectSettingsMapName = "projectSettings"

const fileLog = new Log(false, 'project-v2-interface-storage');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

function loadProjectList(): IProject[] {
  const fnLog = fileLog.sub(false, 'loadProjectList_fn');
  fnLog.pause = true;
  let list = s.read(listName) as IProject[];
  fnLog.log('list=', list);
  if (!_.isArray(list) || !list) list = [];
  const res = prepareProjectList(list);
  return res;
}

function loadDraft(): IProject[] {
  const fnLog = fileLog.sub(false, 'loadDraft_fn');
  fnLog.pause = true;
  let list = s.read(draftName) as IProject[];
  fnLog.log('list=', list);
  if (!_.isArray(list) || !list) list = [];
  const res = prepareProjectList(list);
  return res;
}

function loadProjectSettingsMap():Record<string, IProjectSettings>{
  const fnLog = fileLog.sub(false, 'loadProjectSettingsMap_fn');
  fnLog.pause = true;
  let map:Record<string, IProjectSettings> = s.read(projectSettingsMapName) as Record<string, IProjectSettings>
  if(!map || !_.isMap(map)) map = {}
  return map;
}

function prepareProjectList(list: IProject[]) {
  const fnLog = fileLog.sub(false, 'prepareProjectList_fn');
  fnLog.pause = true;
  return list.map(p => {
    fnLog.log(`[prepareProjectList] 处理项目, ulid=${p.ulid}`);

    // 确保 children 数组存在
    if (!p.children) {
      p.children = [];
      fnLog.log(`[prepareProjectList] 初始化 children 数组`);
    }

    // 确保 children[0] 存在
    if (!p.children[0]) {
      
        // 创建默认值
        const triggerActionGroup = createDefaultTriggerActionGroup();
        p.children[0] = triggerActionGroup;
    }

    const merged = _.merge(createDefaultProject(), p);
    if (!merged.ulid) {
      merged.ulid = ulid();
      fnLog.log(`[数据迁移] 为项目生成 ulid: ${merged.ulid}`);
    }
    return merged;
  });
}

const list: IProject[] = toParentWatchProxy(loadProjectList());
const draft: IProject[] = toParentWatchProxy(loadDraft());

const projectSettingsMap:Record<string, IProjectSettings> = toParentWatchProxy(loadProjectSettingsMap());

function printList() {
  const fnLog = fileLog.sub(false, 'printList_fn');
  fnLog.pause = true;
  fnLog.log('storage initialize list=', objectCountUtils.getObjectCount(list), list);
  list.forEach((p, index) => {
    fnLog.log(
      'storage initialize list item=',
      objectCountUtils.getObjectCount(p),
      'index=',
      index,
      'p=',
      p,
      'isproxy=',
      isProxy(p),
    );
  });
}

function printDraft() {
  const fnLog = fileLog.sub(false, 'printDraft_fn');
  fnLog.pause = true;
  fnLog.log('storage initialize draft=', objectCountUtils.getObjectCount(draft), draft);
  draft.forEach((p, index) => {
    fnLog.log(
      'storage initialize draft item=',
      objectCountUtils.getObjectCount(p),
      'index=',
      index,
      'p=',
      p,
      'isproxy=',
      isProxy(p),
    );
  });
}

function init() {
  const fnLog = fileLog.sub(false, 'printDraft_fn');
  // fnLog.pause = true;
  watchUpdates(list, () => {
    s.write(listName, list, true);
    fnLog.log('list changed', list);
    printList();
  });
  watchUpdates(draft, () => {
    proxyUtils.runPauseProxyFn(() => {
      s.write(draftName, draft, true);
      fnLog.log('draft changed', draft);
    });
    printDraft();
  });
  // 重新启用 projectSettingsMap 的 watchUpdates，确保数据被持久化
  watchUpdates(projectSettingsMap, ()=>{
    s.write(projectSettingsMapName, projectSettingsMap, true)
    console.log('aaaaaaaaaaaaaaaaaaaaaaaaabbbbbbba', JSON.stringify(projectSettingsMap))
  })
  fnLog.log('project-v2 store init', list);
  fnLog.log('project-v2 store init', draft);
}

function saveProject(project: IProject) {
  const fnLog = fileLog.sub(false, 'saveProject_fn');
  // fnLog.pause = true;
  const copy = _.cloneDeep(project);
  let index = list.findIndex(p => p.ulid === copy.ulid);

  fnLog.log('[saveProject] 开始保存 project, ulid=', copy.ulid);
  fnLog.log('[saveProject] 查找结果 index=', index);

  if (index === -1) {
    // 新增 project
    fnLog.log('[saveProject] 新增 project, ulid=', copy.ulid);
    index = list.length;
  } else {
    // 更新现有 project
    const existingProject = list[index];
    fnLog.log('[saveProject] 更新现有 project, ulid=', copy.ulid);
    fnLog.log('[saveProject] 现有 project uuid=', existingProject.uuid);
    fnLog.log('[saveProject] 新 project uuid=', copy.uuid);

    // 只要后端返回了 uuid，就执行合并
    if (copy.uuid) {
      fnLog.log('[saveProject] 检测到后端数据（有 uuid），执行合并');
      fnLog.log('[saveProject] 合并前 existingProject:', JSON.stringify({
        ulid: existingProject.ulid,
        uuid: existingProject.uuid,
        title: existingProject.title,
        childrenLength: existingProject.children?.length
      }));
      fnLog.log('[saveProject] 合并前 copy:', JSON.stringify({
        ulid: copy.ulid,
        uuid: copy.uuid,
        title: copy.title,
        childrenLength: copy.children?.length
      }));

      syncProject(existingProject, copy);

      fnLog.log('[saveProject] 合并后 existingProject:', JSON.stringify({
        ulid: existingProject.ulid,
        uuid: existingProject.uuid,
        title: existingProject.title,
        childrenLength: existingProject.children?.length
      }));
      fnLog.log('[saveProject] 合并完成');
      return;
    }
  }

  list[index] = copy;
  fnLog.log('[saveProject] 直接替换完成, list.length=', list.length);
}

function findSavedProject(ulid: string) {
  return list.find(p => p.ulid === ulid);
}

function findProject(ulid: string) {
  return list.find(p => p.ulid === ulid) || draft.find(p => p.ulid === ulid);
}

function findDraftOrSavedProject(ulid: string) {
  return draft.find(p => p.ulid === ulid) || list.find(p => p.ulid === ulid);
}

function removeProject(ulid: string) {
  const fnLog = fileLog.sub(false, 'removeProject_fn');
  fnLog.pause = true;
  let index = list.findIndex(p => p.ulid === ulid);
  if (index !== -1) {
    list.splice(index, 1);
    removeProjectSettings(ulid)
    s.write(listName, list, true);
    fnLog.log('project removed', ulid, list);
  }
  removeDraft(ulid);
}

function addDraft(project: IProject): IProject {
  const fnLog = fileLog.sub(false, 'addDraft_fn');
  fnLog.pause = true;
  const p = proxyUtils.runPauseProxyFn(() => {
    return _.cloneDeep(project);
  });
  let index = draft.findIndex(p => p.ulid === project.ulid);
  if (index === -1) index = draft.length;
  draft[index] = p;
  addProjectSettings(project.ulid)
  fnLog.log('draft added', project, draft);
  return draft[index];
}

function getDraft(ulid: string) {
  return draft.find(p => p.ulid === ulid);
}

function removeDraft(ulid: string) {
  const fnLog = fileLog.sub(false, 'deleteDraft_fn');
  fnLog.pause = true;
  let index = draft.findIndex(p => p.ulid === ulid);
  if (index !== -1) {
    draft.splice(index, 1);
    s.write(draftName, draft, true);
    removeProjectSettings(ulid)
    fnLog.log('draft deleted', ulid, draft);
  }
}

function getListCopy() {
  return [...list];
}

function getDraftCopy() {
  return [...draft];
}

function getProjectSettings(ulid:string):IProjectSettings | undefined{
  let settings = projectSettingsMap[ulid]
  if(!settings){
    // 兼容一下之前的代码，没有创建setting的话就补充上一个。
    if(getDraft(ulid)){
      addProjectSettings(ulid)
    }
  }
  return settings
}
function addProjectSettings(ulid:string):IProjectSettings{
  console.log('[addProjectSettings] 开始添加/更新 projectSettings, ulid:', ulid);
  const old = projectSettingsMap[ulid]
  if(old){
    // 
    console.log('已经有了projectSettings')
    return old
  }
  const newSettings = createDefaultProjectSettings();
  console.log('[addProjectSettings] 新的 settings:', JSON.stringify(newSettings));

  // 直接更新 projectSettingsMap 代理对象
  projectSettingsMap[ulid] = newSettings;
  console.log('[addProjectSettings] 已赋值给 projectSettingsMap');
  console.log('[addProjectSettings] projectSettingsMap:', JSON.stringify(projectSettingsMap));
  return newSettings
}
function removeProjectSettings(ulid:string):boolean{
  return delete projectSettingsMap[ulid];
}

// 危险操作，仅限于用户退出登陆时使用.
function cleanStorage(){
  list.length = 0;
  draft.length = 0;
}
export const projectStore = {
  list,
  draft,
  init,
  saveProject,
  findSavedProject,
  findProject,
  findDraftOrSavedProject,
  removeProject,
  addDraft,
  getDraft,
  deleteDraft: removeDraft,
  getListCopy,
  getDraftCopy,
  // 供 handlers 使用的扁平化实体存储
  // triggerActionGroupMap,
  // triggerGroupMap,
  // actionGroupMap,
  // triggerMap,
  // actionMap,
  getProjectSettings,
  cleanStorage
};

if (typeof window !== 'undefined') {
  (window as any).getProjectStore = function () {
    fileLog.log('[DEBUG] getProjectStore() called');
    return projectStore;
  };
  init();
  fileLog.log('[DEBUG] projectStore initialized');
}
