
import { useTranslation } from '@fanfanlo';
import { ScriptEditor } from '../../../script-editor';
import { scriptTriggerSimpleTemplate, scriptTriggerAdvancedTemplate, scriptTriggerFullTemplate } from '../scriptTemplates';
import { ITriggerScriptData } from './ITriggerScript.inft';

export function UI(data: ITriggerScriptData) {
  const { t } = useTranslation('droid-project/iproject/triggers/script/script-trigger/content');

  return (
    <ScriptEditor
      data={data}
      simpleTemplate={scriptTriggerSimpleTemplate}
      advancedTemplate={scriptTriggerAdvancedTemplate}
      fullTemplate={scriptTriggerFullTemplate}
      simpleModeDescription={t('modeDescription_simple')}
      advancedModeDescription={t('modeDescription_advanced')}
      fullModeDescription={t('modeDescription_full')}
      type="trigger"
      rows={12}
    />
  );
}
