function read2<T>(key:string, defaultValue?:T):T{
    let script = `var v = com.fanfanlo.lib.store.SharedPrefs.read("${key}");\n v;`
    // console.log('autojs store utils read script=', script)
    let {javaResultString:v, error} = autoWebViewJs.callScript<string>(script)
    // console.log('read_fn key=', key, 'java result string', v,)
    if(v){

            let s = "";
            try{
                s= window.atob(v) ;
                v = s;
                try{
                    let x = JSON.parse(s);
                    // console.log('read', 'x=', x, 'script=', script)
                    return x as T;
                }catch(e){

                    // console.log('script =', script)
                    // console.log('value =', v);
                    // console.log("storage get item json.parse error,but maybe not an error", e);
                }
            }catch(e){
                console.log('atob error', e, 'v=', v, 'script=', script)
                console.trace('atob error')
                v = undefined
            }
    }
    // console.log('return default', `key=${key}`, defaultValue)
    return typeof defaultValue === 'undefined' ? v as T : defaultValue as T;
    // return defaultValue || (v as T);
}

