function write<T>(key:string, v:T):void{
    try{

    // console.log('autojs store utils write', 'key=', key, JSON.stringify(v))
    const s = stringifyBtoaUtf8(v)
    // console.log('autojs store utils write', 's=', s)
    let script = `var v = com.fanfanlo.lib.store.SharedPrefs.write("${key}", "${s}");`;
    // console.log('auto js store utils write', 'script=', script)
    autoWebViewJs.callScript(script);
    // console.log('autoJsStoreUtils write', 'key=', key, 's=', s, 'script=', script)
    }catch(e){
        console.error(`autoJsStoreUtils write error`, (e as any)?.message);
        console.error(`autoJsStoreUtils write error`, e);
    }
}

function stringifyBtoaUtf8<T>(obj: T): string {
  const v = JSON.stringify(obj);
  return btoaUtf8(v);
}


function btoaUtf8(str:string): string {
  const utf8Bytes = new TextEncoder().encode(str);
  let binary = "";
  utf8Bytes.forEach(b => binary += String.fromCharCode(b));
  return btoa(binary);
}

function atobUtf8(base64:string): string {
  const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}
export const autoJsStoreUtils = {
    write,
    read,
    atobUtf8,
    btoaUtf8,
}