import { actionOpenAppUtils } from "./app/action-open-app/IActionOpenApp.inft";
import { actionToAppMainPageUtils } from "./app/to-app-main-page/IToAppMainPage.intf";
import { actionA11yNodeExecuteUtils } from "./a11y/node-execute/node-execute";
import { actionNodeActionUtils } from "./a11y/node-action/IActionNodeAction";
import { actionScriptUtils } from "./script/script-action/IActionScript.inft";

import { Log } from "@fanfanlo";
const fileLog = new Log(false, 'init_actions_f')
fileLog.pause = true;
fileLog.childrenPaused = true;

export function initActions(){
    fileLog.log('[initActions] initializing all action types');

    actionOpenAppUtils.init()
    fileLog.log('[initActions] actionOpenAppUtils initialized');

    actionToAppMainPageUtils.init()
    fileLog.log('[initActions] actionToAppMainPageUtils initialized');

    actionA11yNodeExecuteUtils.init()
    fileLog.log('[initActions] actionA11yNodeExecuteUtils initialized');

    actionNodeActionUtils.init()
    fileLog.log('[initActions] actionNodeActionUtils initialized');

    actionScriptUtils.init()
    fileLog.log('[initActions] actionScriptUtils initialized');

    fileLog.log('[initActions] actionPeriodicReminderUtils initialized');
}
