const fileLog = new Log(true, 'defaults');
fileLog.pause = true;
fileLog.childrenPaused = true;

/**
 * Script Action 的类型标识符
 * 与 v1 保持一致
 */
export const SCRIPT_ACTION_TYPE = 'fanfanlo/javajs/v1/project/components/actions/script/script';

/**
 * 生成简单的ULID（临时使用）
 * TODO: 使用更完善的ULID生成库
 *
 * 注意: 前端创建实体时只生成 ulid,不生成 uuid
 * uuid 由后端在保存时生成
 */
function generateSimpleULID(): string {
  const timestamp = Date.now().toString(36);
  const randomPart = Math.random().toString(36).substring(2, 15);
  return `${timestamp}${randomPart}`.toUpperCase();
}

/**
 * 创建默认的TriggerAction对象
 * 注意: 不自动添加到 Store,需要由调用者手动添加
 *
 * 注意: 前端创建时只有 ulid,uuid 由后端生成
 */
export function createDefaultTriggerAction(): ITriggerAction {
  const fnLog = fileLog.sub(false, 'createDefaultTriggerAction');
  const now = Date.now();
  fnLog.log(`[createDefaultTriggerAction] now=${now}`);

  const ulid = generateSimpleULID();
  fnLog.log(`[createDefaultTriggerAction] ulid=${ulid}`);

  const triggerGroup = createDefaultTriggerGroup();
  fnLog.log(`[createDefaultTriggerAction] triggerGroup.ulid=${triggerGroup.ulid}`);

  const actionGroup = createDefaultActionGroup();
  fnLog.log(`[createDefaultTriggerAction] actionGroup.ulid=${actionGroup.ulid}`);

  const result = {
    id: 0,
    ulid,
    uuid: '',
    ownerUuid: '',
    currentVersion: 1,
    // ULID 引用（用于数据库关联）
    triggerGroupUlid: triggerGroup.ulid,
    actionGroupUlid: actionGroup.ulid,
    // UUID 引用（后端生成）
    triggerGroupUuid: '',
    actionGroupUuid: '',
    // 完整对象引用（运行时使用）
    triggerGroup: triggerGroup,
    actionGroup: actionGroup,
    triggerGroupVersion: 1,
    actionGroupVersion: 1,
    createdAt: now,
    updatedAt: now,
    authorUuid: '',
    history: {},
    historySnapshot: {}
  } as any;

  fnLog.log(`[createDefaultTriggerAction] result.ulid=${result.ulid}`);
  fnLog.log(`[createDefaultTriggerAction] result.triggerGroupUlid=${result.triggerGroupUlid}`);
  fnLog.log(`[createDefaultTriggerAction] result.actionGroupUlid=${result.actionGroupUlid}`);
  fnLog.log(`[createDefaultTriggerAction] result.triggerGroup.ulid=${result.triggerGroup.ulid}`);
  fnLog.log(`[createDefaultTriggerAction] result.actionGroup.ulid=${result.actionGroup.ulid}`);
  return toProxy(result);
}

