/**
 * 创建默认的Project对象
 * 自动创建默认的 TriggerActionGroup
 *
 * 注意: 前端创建时只有 ulid,uuid 由后端生成
 * list 存储子 trigger_action_group 的 ulid
 */
export function createDefaultProject(): IProject {
  const fnLog = fileLog.sub(false, 'createDefaultProject');
  const now = Date.now();
  fnLog.log(`[createDefaultProject] now=${now}`);

  const ulid = generateSimpleULID();
  fnLog.log(`[createDefaultProject] ulid=${ulid}`);

  const triggerActionGroup = createDefaultTriggerActionGroup();
  fnLog.log(`[createDefaultProject] triggerActionGroup.ulid=${triggerActionGroup.ulid}`);

  const result = {
    id: 0,
    ulid,
    uuid: '',
    ownerUuid: '',
    currentVersion: 1,
    type: 'project',
    category: '',
    list: [],// 这个参数是server端传递过来的，储存了children里 triggerActionGroups的uuid
    children: [triggerActionGroup],
    triggerActionGroup,
    createdAt: now,
    updatedAt: now,
    authorUuid: '',
    visibility: 'private',
    childrenVersion: 1,
    history: {},
    historySnapshot: {}
  } as any;

  fnLog.log(`[createDefaultProject] result.ulid=${result.ulid}`);
  fnLog.log(`[createDefaultProject] result.list=`, JSON.stringify(result.list));
  fnLog.log(`[createDefaultProject] result.children.length=${result.children.length}`);
  fnLog.log(`[createDefaultProject] result.triggerActionGroup.ulid=${result.triggerActionGroup.ulid}`);
  return toProxy(result);
}

