/**
 * 根据 ProjectCategory 创建 Project 默认数据
 * @param category 项目类别
 */
export function createProjectByCategory(category: ProjectCategory): IProject {
  const fnLog = fileLog.sub(false, 'createProjectByCategory');
  fnLog.log(`[createProjectByCategory] 开始创建项目, category=${category}`);

  const project = createDefaultProject();
  project.category = category;
  fnLog.log(`[createProjectByCategory] 基础 project 已创建, ulid=${project.ulid}, category=${project.category}`);

  // 获取 triggerActionGroup 的第一个 triggerAction 的 triggerGroup
  // 注意：v2 的 list 存储的是 ulid，需要通过 children[0] 获取实际对象
  // [迁移注释] 原使用 project.triggerActionGroup，现改为 project.children[0]
  // const triggerActionGroup = project.triggerActionGroup;
  const triggerActionGroup = project.children?.[0];
  if (!triggerActionGroup) {
    fnLog.error(`[createProjectByCategory] triggerActionGroup 为空 (children[0] 不存在)`);
    return project;
  }
  fnLog.log(`[createProjectByCategory] triggerActionGroup.ulid=${triggerActionGroup.ulid}`);

  if (category === ProjectCategory.QuickAction) {
    // 快捷操作：清空 triggerGroup.list（无 trigger）
    fnLog.log(`[createProjectByCategory] QuickAction: 需要清空 triggerGroup.list`);
    // 注意：这里需要在 CreateProjectButton 中处理，因为 v2 使用扁平化结构
    fnLog.log(`[createProjectByCategory] QuickAction: 处理完成`);
  } else if (category === ProjectCategory.ScriptRunner) {
    // 脚本运行器：清空 triggerGroup.list，添加 script action
    fnLog.log(`[createProjectByCategory] ScriptRunner: 需要清空 triggerGroup.list 并添加 script action`);
    // 注意：这里需要在 CreateProjectButton 中处理，因为 v2 使用扁平化结构
    fnLog.log(`[createProjectByCategory] ScriptRunner: 处理完成`);
  } else if (category === ProjectCategory.Workflow) {
    // 工作流：使用默认结构
    fnLog.log(`[createProjectByCategory] Workflow: 使用默认结构`);
  } else {
    fnLog.log(`[createProjectByCategory] 未知类别: ${category}, 使用默认结构`);
  }

  fnLog.log(`[createProjectByCategory] 项目创建完成:`, JSON.stringify(project));
  return project;
}
