/**
 * 项目历史记录管理
 * 参考 project/src/history/projectsHistoryMap.ts
 */
import { IProject } from '../entities/IProject';
import { getProxyTarget, proxyUtils } from "@fanfanlo";
import _ from "lodash";

export interface IProjectHistory {
  index: number
  project: IProject
  date: string
}

export const projectsHistoryMap = new Map<string, IProjectHistory[]>()

export function addProjectHistory(history: IProjectHistory) {
  console.log('[addProjectHistory] 开始添加历史记录')
  console.log('[addProjectHistory] history.project.ulid:', history.project.ulid)
  proxyUtils.runPauseProxyFn(() => {
    history.project = _.cloneDeep(getProxyTarget(history.project))
  })
  const p = history
  const projectId = history.project.ulid
  console.log('[addProjectHistory] projectId:', projectId)
  const list = projectsHistoryMap.get(projectId)
  if (!list) {
    console.log('[addProjectHistory] 创建新历史列表')
    projectsHistoryMap.set(projectId, [p])
    return
  }
  console.log('[addProjectHistory] 追加到现有历史列表, 当前长度:', list.length)
  list.push(p)
}

export function getProjectHistory(projectId: string) {
  console.log('[getProjectHistory] projectId:', projectId)
  const result = projectsHistoryMap.get(projectId) || []
  console.log('[getProjectHistory] 结果长度:', result.length)
  return result
}

export function removeProjectHistory(projectId: string) {
  console.log('[removeProjectHistory] projectId:', projectId)
  projectsHistoryMap.delete(projectId)
}

export function getProjectLastHistory(projectId: string) {
  console.log('[getProjectLastHistory] projectId:', projectId)
  const list = getProjectHistory(projectId)
  const result = list[list.length - 1]
  if (result) {
    console.log('[getProjectLastHistory] 找到最后一条, index:', result.index)
  } else {
    console.log('[getProjectLastHistory] 无历史记录')
  }
  return result
}

export function takeProjectSnapshoot(project: IProject): boolean {
  console.log('[takeProjectSnapshoot] 开始拍摄项目快照')
  console.log('[takeProjectSnapshoot] project.ulid:', project.ulid)
  const last = getProjectLastHistory(project.ulid)
  if (last && _.isEqual(last.project, project)) {
    console.log('[takeProjectSnapshoot] 项目未变更，跳过')
    return false
  }
  const newIndex = last ? last.index + 1 : 0
  console.log('[takeProjectSnapshoot] 添加新快照, index:', newIndex)
  addProjectHistory({
    index: newIndex,
    project,
    date: new Date().toISOString()
  })
  return true
}

export function projectHistoryIsChanged(project: IProject): boolean {
  console.log('[projectHistoryIsChanged] project.ulid:', project.ulid)
  const last = getProjectLastHistory(project.ulid)
  const isChanged = !last || !_.isEqual(last.project, project)
  console.log('[projectHistoryIsChanged] isChanged:', isChanged)
  return isChanged
}

export function isSameProjectHistoryId(id: number, projectId: string): boolean {
  console.log('[isSameProjectHistoryId] id:', id, 'projectId:', projectId)
  const last = getProjectLastHistory(projectId)
  const isSame = last?.index === id
  console.log('[isSameProjectHistoryId] isSame:', isSame)
  return isSame
}
