import { ulid } from "ulid";
import { actionGroupUtils, IActionGroup } from "../action/IActionGroup.intf";
import { INameId } from "../common";
import { ITriggerGroup, triggerGroupUtils } from "../trigger/ITriggerGroup.intf";
import { createMergeToDefaultData } from "../utils/mergeToDefaultData";
export interface ITriggerAction extends INameId{
    type:string
    id:string,
    triggerGroup:ITriggerGroup
    actionGroup:IActionGroup
}


export function createDefaultTriggerAction():ITriggerAction{
    return {
        type:'triggerAction',
        id:ulid(),
        name:'',
        triggerGroup:triggerGroupUtils.createDefaultData(),
        actionGroup:actionGroupUtils.createDefaultData()
    }
}   

export interface ITriggerActionUtils{
    type:string
    createDefaultData:()=>ITriggerAction
    mergeDataToDefaultData:(data:Partial<ITriggerAction>)=>ITriggerAction
}

export function createTriggerActionUtils(type:string, createDefaultData:()=>ITriggerAction):ITriggerActionUtils{
    return {
        type,
        createDefaultData,
        mergeDataToDefaultData:createMergeToDefaultData(createDefaultData)
    }
}   

