import { ulid } from "ulid"
import { createTriggerUtils, ITriggerData, ITriggerShellData, ITriggerJavaData } from "@droid/project-interface"
import { a11yNamespace } from "../a11y-namespace"
import { UI } from "./UI"
import { ManifestPermission } from "@droid/android"
import { RhinoInjectNames } from "@app/static"
import { NodeSelectorChain } from "./selector-chain"

export const triggerNodeTriggerType = `${a11yNamespace}node-trigger`
const type = triggerNodeTriggerType

/**
 * NodeTrigger 的 Java 端数据结构
 */
export interface ITriggerNodeTriggerJavaData extends ITriggerJavaData {
    /** 包名 */
    pn: string
    /** Activity 名 */
    an: string
    /** 页面类名 (可选) */
    cn?: string
    /** Selector链式操作配置 */
    selectorChain: NodeSelectorChain
}

/**
 * NodeTrigger 的完整数据结构
 */
export interface ITriggerNodeTriggerData extends ITriggerData<ITriggerShellData, ITriggerNodeTriggerJavaData> {
    javaData: ITriggerNodeTriggerJavaData
}

/**
 * 创建默认的 NodeTrigger 数据
 */
function createDefaultData(): ITriggerNodeTriggerData {
    console.log('[ITriggerNodeTrigger.createDefaultData] 开始创建默认数据')

    const id = ulid()
    console.log('[ITriggerNodeTrigger.createDefaultData] 生成id:', id)

    const permissions = [
        {
            name: '辅助功能权限',
            value: ManifestPermission.BIND_ACCESSIBILITY_SERVICE,
            reason: '需要辅助功能来监听应用切换和查找节点'
        }
    ]
    console.log('[ITriggerNodeTrigger.createDefaultData] 权限数量:', permissions.length)

    const injects: ([typeof RhinoInjectNames.a11yModel, string])[] = [
        [RhinoInjectNames.a11yModel, 'a11yModel']
    ]
    console.log('[ITriggerNodeTrigger.createDefaultData] 注入配置数量:', injects.length)

    const defaultData: ITriggerNodeTriggerData = {
        id,
        type,
        name: 'triggerNodeTrigger',
        permissions,
        injects,
        javaData: {
            pn: '',
            an: '',
            cn: '',
            selectorChain: {
                operations: []
            }
        }
    }
    console.log('[ITriggerNodeTrigger.createDefaultData] defaultData:', defaultData)
    return defaultData
}

/**
 * 初始化函数
 */
function init() {
}

/**
 * NodeTrigger 工具对象
 */
export const triggerNodeTriggerUtils = createTriggerUtils<ITriggerNodeTriggerData>(type, init, createDefaultData, UI)
