import {
  IThreeLayerID,
  IR2Paths,
  IEntityBase,
  IMetadata
} from '../types/base';
import { IOwnership } from '../types/ownership';
import { IVisibilityChild } from '../types/visibility';
import { IFork } from '../types/fork';
import { IVersionContainer } from '../types/version';
import { ITreeStructure } from '../types/tree';
import { ITriggerAction } from './ITriggerAction';
import { mergeToDefaultData } from '../utils/mergeToDefaultData';
import { ulid } from 'ulid';
import { triggerGroupUtils } from './ITriggerGroup';
import { actionGroupUtils } from './IActionGroup';

// === 类型常量 ===
export const triggerActionGroupType = 'triggerActionGroup'

/**
 * 触发器-动作组接口
 * 对应SQL表：project_trigger_action_group
 * 对应Go结构：ProjectTriggerActionGroup
 *
 * 触发器-动作组是一个容器，存储 TriggerAction（触发器-动作配对）的列表。
 * 每个 TriggerAction 关联一个 TriggerGroup（包含触发器集合）和一个 ActionGroup（包含动作集合）。
 *
 * list字段存储的是子trigger_action的ULID列表
 * children字段存储完整的子trigger_action对象列表（运行时填充）
 */
export interface ITriggerActionGroup extends
  IThreeLayerID,
  IEntityBase,
  IR2Paths,
  IOwnership,
  IVisibilityChild,
  IFork,
  IVersionContainer,
  ITreeStructure<ITriggerAction>,
  IMetadata
{
  // list字段继承自ITreeStructure，存储子trigger_action的ULID
  // children字段继承自ITreeStructure<ITriggerAction>，存储完整对象
}

// === 创建默认 TriggerAction ===
export function createDefaultTriggerAction(): ITriggerAction {
  console.log('[createDefaultTriggerAction] 开始创建')
  const triggerGroup = triggerGroupUtils.createDefaultData()
  console.log('[createDefaultTriggerAction] triggerGroup.ulid:', triggerGroup.ulid)
  const actionGroup = actionGroupUtils.createDefaultData()
  console.log('[createDefaultTriggerAction] actionGroup.ulid:', actionGroup.ulid)
  const triggerActionUlid = ulid()
  console.log('[createDefaultTriggerAction] triggerAction.ulid:', triggerActionUlid)
  return {
    id: 0,
    ulid: triggerActionUlid,
    uuid: '',
    triggerGroupUuid: triggerGroup.uuid,
    triggerGroupUlid: triggerGroup.ulid,
    actionGroupUuid: actionGroup.uuid,
    actionGroupUlid: actionGroup.ulid,
    triggerGroup,
    actionGroup,
    createdAt: Date.now(),
    updatedAt: Date.now()
  } as ITriggerAction
}

// === 创建默认 TriggerActionGroup ===
export function createDefaultTriggerActionGroup(): ITriggerActionGroup {
  console.log('[createDefaultTriggerActionGroup] 开始创建')
  const triggerAction = createDefaultTriggerAction()
  console.log('[createDefaultTriggerActionGroup] triggerAction.ulid:', triggerAction.ulid)
  const triggerActionGroupUlid = ulid()
  console.log('[createDefaultTriggerActionGroup] triggerActionGroup.ulid:', triggerActionGroupUlid)
  return {
    id: 0,
    ulid: triggerActionGroupUlid,
    uuid: '',
    list: [triggerAction.ulid],
    // 初始化children（web端主要使用）
    children: [triggerAction],
    checks: [[true]],
    isSequential: false,
    createdAt: Date.now(),
    updatedAt: Date.now()
  } as ITriggerActionGroup
}

export function mergeTriggerActionGroupToDefaultData(data: Partial<ITriggerActionGroup>): ITriggerActionGroup {
  console.log('[mergeTriggerActionGroupToDefaultData] 开始合并')
  const result = mergeToDefaultData(createDefaultTriggerActionGroup, data)
  console.log('[mergeTriggerActionGroupToDefaultData] 合并完成, ulid:', result.ulid)
  return result
}
