import { toProxy, useProxyWatchUpdates, useTranslation, proxyWatch } from '@fanfanlo';
import { Box, Autocomplete, TextField, Chip, Stack, Typography } from '@mui/material';
import { useState, useRef, useEffect } from 'react';
import { InjectKeyOptions, InjectKey, getInjectKeyDescription } from '@app/static';

// 日志前缀
const LOG_PREFIX = '[InjectsEditorAdapter]';

interface InjectsEditorAdapterProps {
  /**
   * 注入数据对象（直接修改此对象的 injects 属性）
   */
  data: {
    injects?: (InjectKey | [InjectKey, string])[]
  };
}

/**
 * Injects 编辑器适配器
 * 使用 MUI Autocomplete 组件进行多选
 */
export function InjectsEditorAdapter({ data }: InjectsEditorAdapterProps) {
  console.log(`${LOG_PREFIX} 组件初始化`);
  console.log(`${LOG_PREFIX} 输入 data.injects:`, JSON.stringify(data.injects));

  const { t } = useTranslation('droid-project/iproject/script-editor/content');

  // 初始化标记，防止初始化时触发更新
  const isInitializedRef = useRef(false);

  // 加载所有 inject 的描述
  const [injectOptions, setInjectOptions] = useState<Array<{
    option: typeof InjectKeyOptions[number];
    description: string;
  }>>([]);

  // 初始化 inject 选项
  useEffect(() => {
    console.log(`${LOG_PREFIX} 初始化 inject 选项`);

    (async () => {
      const options = await Promise.all(
        InjectKeyOptions.map(async (option) => {
          console.log(`${LOG_PREFIX} 加载 inject 描述: ${option.i18nKey}`);
          const description = await getInjectKeyDescription(option.i18nKey);
          console.log(`${LOG_PREFIX} 加载完成: ${option.i18nKey} = ${description}`);
          return {
            option,
            description,
          };
        })
      );

      console.log(`${LOG_PREFIX} 所有 inject 选项加载完成，共 ${options.length} 个`);
      setInjectOptions(options);
    })();
  }, []);

  // 获取当前选中的 inject 键名
  const currentInjectKeys = (data.injects || []).map(inject => {
    if (typeof inject === 'string') {
      console.log(`${LOG_PREFIX} 提取 inject 键名 (字符串格式): ${inject}`);
      return inject;
    } else {
      console.log(`${LOG_PREFIX} 提取 inject 键名 (数组格式): ${inject[0]}`);
      return inject[0];
    }
  });

  console.log(`${LOG_PREFIX} 当前选中的 inject 键名: ${JSON.stringify(currentInjectKeys)}`);

  // 处理 inject 选择变化
  const handleInjectsChange = (event: any, newValues: typeof InjectKeyOptions[number][]) => {
    console.log(`${LOG_PREFIX} inject 选择变化事件触发`);
    console.log(`${LOG_PREFIX} 新选中的数量: ${newValues.length}`);

    // 转换为 InjectKey[]
    const newInjectKeys: InjectKey[] = newValues.map(v => {
      const key = v.key as InjectKey;
      console.log(`${LOG_PREFIX} 添加 inject 键名: ${key}`);
      return key;
    });
    console.log(`${LOG_PREFIX} 新的 inject 键名列表: ${JSON.stringify(newInjectKeys)}`);

    // 更新 data.injects
    data.injects = newInjectKeys;
    console.log(`${LOG_PREFIX} data.injects 已更新: ${JSON.stringify(data.injects)}`);
  };

  // 获取当前选中的 option 对象
  const selectedOptions = InjectKeyOptions.filter(option => {
    const isSelected = currentInjectKeys.includes(option.key as InjectKey);
    console.log(`${LOG_PREFIX} 检查 option 是否选中: ${option.key} = ${isSelected}`);
    return isSelected;
  });

  console.log(`${LOG_PREFIX} 选中的 option 数量: ${selectedOptions.length}`);

  return (
    <Box>
      <Stack direction="column" spacing={1}>
        <Typography variant="body2" sx={{ fontWeight: 500 }}>
          {t('InjectsEditorAdapter.label')}:
        </Typography>
        <Autocomplete
          multiple
          options={InjectKeyOptions}
          getOptionLabel={(option) => {
            console.log(`${LOG_PREFIX} getOptionLabel: ${option.key}`);
            // 查找对应的描述
            const injectOption = injectOptions.find(io => io.option.key === option.key);
            const description = injectOption?.description || '';
            console.log(`${LOG_PREFIX} 显示文本: ${option.key} - ${description}`);
            // 显示格式: "key - 描述"
            return description ? `${option.key} - ${description}` : option.key;
          }}
          value={selectedOptions}
          onChange={handleInjectsChange}
          renderInput={(params) => (
            <TextField
              {...params}
              variant="outlined"
              size="small"
              placeholder={t('InjectsEditorAdapter.placeholder')}
            />
          )}
          renderTags={(value, getTagProps) =>
            value.map((option, index) => {
              console.log(`${LOG_PREFIX} renderTags: ${option.key}`);
              // 从 getTagProps 返回值中解构 key，单独传递
              const { key, ...chipProps } = getTagProps({ index });
              return (
                <Chip
                  key={option.key}
                  label={option.key}
                  {...chipProps}
                  size="small"
                />
              );
            })
          }
          isOptionEqualToValue={(option, value) => option.key === value.key}
          groupBy={(option) => option.group}
          sx={{
            width: '100%'
          }}
        />
        {injectOptions.length > 0 && selectedOptions.length > 0 && (
          <Box sx={{ fontSize: '12px', color: '#666', maxHeight: '200px', overflow: 'auto' }}>
            <Typography variant="caption" sx={{ fontWeight: 500, display: 'block', mb: 1 }}>
              {t('InjectsEditorAdapter.description')}:
            </Typography>
            {selectedOptions.map((option) => {
              const injectOption = injectOptions.find(io => io.option.key === option.key);
              console.log(`${LOG_PREFIX} 渲染 inject 描述: ${option.key} = ${injectOption?.description}`);
              return (
                <Box key={option.key} sx={{ mb: 1 }}>
                  <Box sx={{ fontWeight: 500 }}>{option.key}</Box>
                  <Box sx={{ color: '#999', fontSize: '11px' }}>
                    {injectOption?.description}
                  </Box>
                </Box>
              );
            })}
          </Box>
        )}
      </Stack>
    </Box>
  );
}
