import { ulid } from 'ulid';

/**
 * 将 V1 触发器/动作对象转换为 V2 格式
 * V1: { id: ulid, type, name, ... }
 * V2: { id: number, ulid: string, uuid: string, type, name, ... }
 *
 * 注意: uuid 由后端生成,前端创建时留空
 */
export function adaptV1ToV2<T extends { id: string }>(v1Object: T): any {
  const { id: v1Id, ...rest } = v1Object;

  return {
    id: 0, // 临时 ID,数据库会分配真实 ID
    ulid: v1Id, // V1 的 id 就是 ULID
    uuid: '', // 由后端生成,前端创建时留空
    ...rest
  };
}
